INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(969, 'plPL', 'Niech szczęście ci sprzyja', 'Ach, od razu widzę, jak na ciebie patrzę – chcesz zrobić amulet na szczęście. Mau\'ari zawsze wie!$B$BNa południu znajdziesz kanion, a w nim olbrzymy z litego lodu. Olbrzymy czasem noszą przy sobie odłamki, ale zawsze możesz $gsam:sama; je zebrać w kanionie. Te odłamki mają potężną moc odbijania.$B$BPrzynieś mi 4 odłamki Mroźnych Maczug, a mój amulet na szczęście będzie twój.', 'Zbierz 4 odłamki Mroźnych Maczug dla znachorki Mau\'ari w Wiecznowidzie.', '', 'Wróć do znachorki Mau\'ari w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(975, 'plPL', 'Skrytka Mau\'ari', 'No, zanim dam ci ten amulet, lepiej wytłumaczę, jak go używać.$B$BJeśli będziesz go nosić przy sobie, zobaczysz, że stworzenia, z którymi walczysz, zostawiają pewne przedmioty. Jeśli nie będziesz mieć amuletu przy sobie, nie znajdziesz ich. Rozumiesz?$B$BTe szczególne przedmioty poznasz po nazwie – nazywają się e\'ko. Jeśli znajdziesz któryś z nich, przynieś go starej Mau\'ari, a ona ci pomoże.$B$BZaczekaj tu, a ja przygotuję twój amulet.', 'Za chwilę porozmawiaj ponownie ze znachorką Mau\'ari, aby otrzymać amulet na szczęście.', '', '', '', '', '', '', 0),
(977, 'plPL', 'Daleko jeszcze, yeti?', 'Skoro mam już czym osłonić ruchome części mechanizmu, potrzebuję jeszcze tylko jednej rzeczy. A właściwie dwóch. Dwóch rogów!$B$BPatriarchowie i matrony Lodowego Ostu mają największe rogi, więc to oczywiście ich chcę. Te yeti zamieszkują jaskinię na południowym wschodzie. Jest ich tam mnóstwo, więc nie powinno być kłopotu z ich znalezieniem.$B$BPamiętaj, chcę tylko te najładniejsze – żadnych obitych ani ułamanych rogów, proszę!', 'Zbierz 2 nieskazitelne rogi yeti dla Umi Rumplesnicker w Wiecznowidzie.', '', 'Wróć do Umi Rumplesnicker w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(3783, 'plPL', 'Daleko jeszcze, yeti?', 'Moi przyjaciele zawsze wpadają na świetne pomysły. Nigdy nie czułam, że mogę im dorównać... aż do dziś! Właśnie narysowałam plany czegoś wspaniałego! Jeśli obiecasz nikomu nie mówić, zdradzę ci sekret...$B$BZbuduję mechanicznego yeti! Moi przyjaciele na pewno się przestraszą, kiedy go zobaczą, a jak już ochłoną, wiem, że będą pod wrażeniem!$B$BNa początek potrzebuję gęstego futra z yeti Lodowego Ostu. Pomożesz mi? Znajdziesz je na południowym wschodzie.', 'Zbierz 10 gęstych futer yeti dla Umi Rumplesnicker w Wiecznowidzie.', '', 'Wróć do Umi Rumplesnicker w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(4801, 'plPL', 'E\'ko mroźnych szablobestii', '', '', '', 'Wróć do znachorki Mau\'ari w Zimozdroju.', '', '', '', '', 0),
(4802, 'plPL', 'E\'ko Zimospadu', '', '', '', 'Wróć do znachorki Mau\'ari w Zimozdroju.', '', '', '', '', 0),
(4803, 'plPL', 'E\'ko skałozębnych niedźwiedzi', '', '', '', 'Wróć do znachorki Mau\'ari w Zimozdroju.', '', '', '', '', 0),
(4804, 'plPL', 'E\'ko chimer z Zimnych Wichrów', '', '', '', 'Wróć do znachorki Mau\'ari w Zimozdroju.', '', '', '', '', 0),
(4805, 'plPL', 'E\'ko Lodowego Ostu', '', '', '', 'Wróć do znachorki Mau\'ari w Zimozdroju.', '', '', '', '', 0),
(4806, 'plPL', 'E\'ko Mroźnych Maczug', '', '', '', 'Wróć do znachorki Mau\'ari w Zimozdroju.', '', '', '', '', 0),
(4807, 'plPL', 'E\'ko dziczołaków', '', '', '', 'Wróć do znachorki Mau\'ari w Zimozdroju.', '', '', '', '', 0),
(4809, 'plPL', 'Rogi chimer z Zimnych Wichrów', 'Mam większość tego, czego potrzebuje Tinkee, ale brakuje mi jednego ważnego składnika – rogów chimer z Zimnych Wichrów. Rogi chimer z Zimnych Wichrów w Zimozdroju to skoncentrowane źródło zimna, ale nadają się tylko nieskazitelne, nienaruszone rogi! Potrzebuję ich zapasu, żeby skompletować zamówienie Tinkee.$B$BPrzynieś mi nienaruszone rogi chimer, a przygotuję paczkę dla Tinkee.', 'Zbierz 8 nienaruszonych rogów chimer z Zimnych Wichrów.', '', 'Wróć do Felnoka Stalosprężyna w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(4861, 'plPL', 'Rozwścieczone dziczołaki', 'Hej, $gchłopcze:dziewczyno;! Jakieś krwiożercze dziczołaki przegoniły mnie z mojego obozu w południowym Zimozdroju! No cóż, chyba za bardzo zbliżyłem się do czegoś, czego pilnowały.$B$BLedwo uszedłem cało, a obawiam się, że jeden z moich kumpli nie miał tyle szczęścia. Odważysz się stawić czoła dziczołakom i pójść do obozu? Bardzo potrzebuję moich zapasów, a chciałbym też odzyskać amulet, który wczoraj wykopałem na stanowisku wykopaliskowym.', 'Odszukaj zniszczony obóz i zapasy Jarona Kamieniarza w południowym Zimozdroju.', '', '', '', '', '', '', 0),
(4863, 'plPL', 'Rozwścieczone dziczołaki', 'Rozglądając się, nie widzisz tu wiele rzeczy, które mogłyby się przydać Jaronowi. Zauważasz jednak, że znaleziona przez ciebie skrzynia została rozbita, zupełnie jakby właśnie na niej zależało dziczołakom...$B$BNa wschodzie ledwo dostrzegasz porzucony wóz. Może tam znajdziesz rzeczy Jarona. Warto sprawdzić.', 'Znajdź rozbity wóz Jarona Kamieniarza.', '', '', '', '', '', '', 0),
(4864, 'plPL', 'Rozwścieczone dziczołaki', 'Po obejrzeniu zawartości skrzynki uznajesz, że Jaron mógłby wykorzystać narzędzia i inne rzeczy, które są w środku. Nigdzie jednak nie ma śladu amuletu.$B$BWygląda na to, że dziczołaki zamieszkują ziemie na północ i na wschód stąd, więc postanawiasz, że następnym krokiem będzie stawienie czoła tym stworzeniom i odebranie im amuletu.', 'Zabierz zapasy Jarona ze śniegu, a potem znajdź dziczołaka, który ukradł amulet, o którym mówił Jaron.$B$BZanieś zapasy Jarona i amulet z niebieskimi piórami Jaronowi Kamieniarzowi do chaty w Zimozdroju.', '', 'Wróć do Jarona Kamieniarza w Wiosce Spadającej Gwiazdy w Zimozdroju.', '', '', '', '', 0),
(4970, 'plPL', 'Prowiant dla mroźnych szablobestii', 'Jeśli chcesz się wykazać, możesz zacząć od bardzo prostego, ale bardzo ważnego zadania.$B$BZbierz mięso chimer i skałozębnych niedźwiedzi z okolicy. Przynieś mi je, abym $gmógł:mogła; nakarmić nim szkolone mroźne szablobestie.', 'Zbierz 5 porcji mięsa niedźwiedzia skałozębnego i 5 porcji mięsa chimery z Zimnych Wichrów dla Riverna Mroźnego Wiatru w Zimozdroju.', '', 'Wróć do Riverna Mroźnego Wiatru przy Skale Mroźnych Szablobestii w Zimozdroju.', '', '', '', '', 0),
(5047, 'plPL', 'Finkle Einhorn do usług!', 'Malyfousa Mrocznego Młota znajdziesz w Wiecznowidzie, $N. Powiedz mu, że „z Finkle\'em wszystko gra” i że kombinezon działa bez zarzutu.$B$BA potem daj mu to:$B$B<Finkle wręcza ci świecący kawał mięsa.>$B$BWyrwałem to z trzewi bestii podczas moich „wakacji”.$B$BZałożę się, że Malyfous dość dokładnie oceni, co da się zrobić z części takiego potwora!$B$BAch, pewnie nie wiesz, gdzie jest Wiecznowid, co? Do Zimozdroju, $gkolego:panienko;!', 'Porozmawiaj z Malyfousem Mrocznym Młotem w Wiecznowidzie.', '', '', '', '', '', '', 0),
(5054, 'plPL', 'Ursius ze skałozębnych', 'W ośnieżonych górach Zimozdroju, na północnym zachodzie, zręczny łowca podchodzi swoją ofiarę... Mówię o Ursiusie ze skałozębnych niedźwiedzi, zwinnej i sprytnej bestii.$B$BTeraz posyłam cię przeciwko niemu. Krąży po łagodnych wzgórzach na północny zachód od Wiecznowidu. Znajdź go i upoluj, zanim odkryje twoje zamiary.$B$BWszyscy, którzy stanęli przeciwko Ursiusowi, szybko przekonali się, że to oni są ofiarą, a on łowcą. Miej się na baczności.', 'Storm Cieniste Kopyto z Wiecznowidu w Zimozdroju chce, abyś $gzabił:zabiła; Ursiusa.', '', 'Wróć do Storma Cienistego Kopyta w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5055, 'plPL', 'Brumeran z Zimnych Wichrów', 'Szybka i sprytna Brumeran bezszelestnie szybuje nad śnieżnymi krajobrazami południowego Zimozdroju. Ale nie daj się zwieść jej wdziękowi i nie myśl, że jest niegroźna. Wszyscy, którzy wejdą jej w drogę, słono za to płacą, często własnym życiem.$B$BOdszukaj Brumeran z Zimnych Wichrów wśród chimer. Pokonaj ją, a potem znów wróć do mnie.', 'Storm Cieniste Kopyto z Wiecznowidu w Zimozdroju chce, abyś $gzabił:zabiła; Brumeran.', '', 'Wróć do Storma Cienistego Kopyta w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5056, 'plPL', 'Shy-Rotam', 'W północnym Zimozdroju wielkie koty zbierają się wokół okazałego punktu orientacyjnego, zwanego Skałą Mroźnych Szablobestii. Przywódczyni tych kotów nosi imię Shy-Rotam. Pokonanie matriarchy mroźnych szablobestii przysporzyłoby ci wiele szacunku w oczach twoich pobratymców.$B$BIdź znów w surowe dzicze i zbierz tam święte mięso mroźnych szablobestii. Znajdź kamień Shy-Rotam i złóż je na nim. Mięso jej pobratymców położone przed kamieniem przywoła rozgniewaną Shy-Rotam.$B$BBądź $ggotów:gotowa; na jej furię i pokonaj ją.', 'Storm Cieniste Kopyto z Wiecznowidu w Zimozdroju chce, abyś $gpokonał:pokonała; Shy-Rotam.', '', 'Wróć do Storma Cienistego Kopyta w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5057, 'plPL', 'Dawne dokonania', 'Zanim ze mną $grozmawiałeś:rozmawiałaś;, $N, słyszałem już o twoich dokonaniach... o tym, że masz nieugiętą wolę, by się wykazać, i wyjątkowe zdolności jako $c. Teraz wiem, że to prawda.$B$BCi, którzy tak jak ty się wyróżniają, zasługują na uznanie. Zanieś ten znacznik mojemu przyjacielowi w Gromowych Urwiskach, Melorowi Kamiennemu Kopytu. Na pewno cię pamięta i pamięta, czego $gdokonałeś:dokonałaś; tak dawno temu. Opowiedz mu o swoich ostatnich zwycięstwach i nigdy nie zapominaj, czego dziś $gdokonałeś:dokonałaś;.', 'Zanieś znacznik Storma Cienistego Kopyta Melorowi Kamiennemu Kopytu w Gromowych Urwiskach.', '', '', '', '', '', '', 0),
(5063, 'plPL', 'Czapka szkarłatnego uczonego', 'Piękniejszej czapki możesz już nigdy nie zobaczyć. Z nieskazitelnej skóry Bestii nasi biegli rzemieślnicy stworzą najwspanialszy kapelusz, jaki kiedykolwiek mógłby wymarzyć sobie iluzjonista!$B$BPięćdziesiąt sztuk złota wraz z wymienionymi przedmiotami, a twoją głowę ozdobi Czapka szkarłatnego uczonego:$B$B* Nieskazitelna skóra Bestii.$B$B* Postrzępione szwy plugastwa.$B$B* Tajemne kryształy.$B$B* Zaczarowana szkarłatna nić.$B$BPODZIWIAJ!', 'Aby wykonać Czapkę szkarłatnego uczonego, musisz przynieść Malyfousowi Mrocznemu Młotowi następujące przedmioty: 1 nieskazitelną skórę Bestii, 5 postrzępionych szwów plugastwa, 8 tajemnych kryształów, 5 zaczarowanych szkarłatnych nici.$B$BMusisz też zapłacić 50 sztuk złota za wykonanie przedmiotu.', '', 'Wróć do Malyfousa Mrocznego Młota w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5067, 'plPL', 'Nogawice arkanów', 'Choć nikomu jeszcze nie udało się wykonać takiego przedmiotu, uważa się, że jest to możliwe – w odpowiednich okolicznościach.$B$BJeśli poszukiwacz tajemnej wiedzy pragnie tchnąć w nogawice ogromną moc, musi znaleźć:$B$B* Nieskazitelną skórę Bestii.$B$B* Postrzępione szwy plugastwa.$B$B* Sztabki arkanitu.$B$B* Płyn do balsamowania Reza Szepta Mrozu.$B$BPODZIWIAJ!', 'Aby wykonać Nogawice arkanów, musisz przynieść Malyfousowi Mrocznemu Młotowi następujące przedmioty: 1 nieskazitelną skórę Bestii, 5 postrzępionych szwów plugastwa, 5 sztabek arkanitu, 5 porcji płynu do balsamowania Reza Szepta Mrozu.$B$BMusisz też zapłacić 50 sztuk złota za wykonanie przedmiotu.', '', 'Wróć do Malyfousa Mrocznego Młota w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5068, 'plPL', 'Napierśnik głodu krwi', 'Mówi się, że powstał tylko jeden Napierśnik głodu krwi i że wykonano go dla legendarnej zabójczyni Garony. Wątpliwe, czy ten świat ujrzy kiedykolwiek drugi.$B$BMimo to! Nasi mistrzowie rzemiosła mogą odtworzyć ten przedmiot, jeśli dostaną niezbędne składniki:$B$B* Nieskazitelną skórę Bestii.$B$B* Postrzępione szwy plugastwa.$B$B* Sztabki arkanitu.$B$B* Skórę cienia.$B$BPODZIWIAJ!', 'Aby wykonać Napierśnik głodu krwi, musisz przynieść Malyfousowi Mrocznemu Młotowi następujące przedmioty: 1 nieskazitelną skórę Bestii, 10 postrzępionych szwów plugastwa, 5 sztabek arkanitu, 5 skór cienia.$B$BMusisz też zapłacić 50 sztuk złota za wykonanie przedmiotu.', '', 'Wróć do Malyfousa Mrocznego Młota w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5083, 'plPL', 'Ognista woda Zimospadu', 'Fiolka, którą $gzabrałeś:zabrałaś; furbolgowi z plemienia Zimospadu, jest pusta, ale w środku widać kilka kropel dziwnego zielonego płynu. Niemal świeci.$B$BCzy to coś ważnego?$B$BDonova Snowden pewnie będzie mogła powiedzieć ci więcej – od dłuższego czasu obozuje przy gorących źródłach w Zimozdroju.', 'Zanieś pustą flaszkę po ognistej wodzie Donovie Snowden w Zimozdroju.', '', '', '', '', '', '', 0),
(5103, 'plPL', 'Gorąca, ognista śmierć', 'Z tego człowieka zostało tylko kilka zwęglonych kości. Wygląda na to, że zginął na wyciągnięcie ręki od tego, po co przyszedł – niewypalonych rękawic płytowych.$B$BMoże warto zabrać rękawice i uciec z ognia?', 'Ktoś na tym świecie musi wiedzieć, co zrobić z tymi rękawicami. Powodzenia!', '', '', '', '', '', '', 0),
(5123, 'plPL', 'Ostatni element', 'Dziennik, który $gznalazłeś:znalazłaś; przy najwyższym wodzu, wygląda na obszerny, ale po przejrzeniu kilku stron stwierdzasz, że nie potrafisz odczytać tekstu. Znaki są tak niezdarne i koślawe, że nie wiesz, czy ktokolwiek zdołałby je przeczytać.$B$BAle może Donova potrafi ci powiedzieć, co tam jest napisane...', 'Zanieś niezdarnie spisany dziennik Donovie Snowden w Zimozdroju.', '', '', '', '', '', '', 0),
(5124, 'plPL', 'Ogniste rękawice płytowe', 'Na brodę Thaurissana!$B$BGdzie je $gznalazłeś:znalazłaś;?$B$BA co ważniejsze, czy zechcesz się z nimi rozstać? Oczywiście zapłacę ci za tak szlachetny gest.$B$BPowiem ci tak, $N. Jeśli dasz mi te niewypalone rękawice, nauczę cię, jak zrobić całkiem własną parę. Musisz tylko zebrać dla mnie części, żebym mógł dopracować dokładny przepis.$B$BUmowa stoi??$B$BOto lista tego, czego potrzebuję. Niezaklęte torium wyłożę sam, skoro ty dostarczasz rękawice.$B', 'Przynieś Malyfousowi Mrocznemu Młotowi 6 sztabek zaklętego torium, 2 esencje ognia i 4 gwiezdne rubiny. Musisz też oddać niewypalone rękawice płytowe.', '', 'Wróć do Malyfousa Mrocznego Młota w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5126, 'plPL', 'Opowieść Loraxa', 'Satyr krąży w tę i z powrotem i mówi do siebie. Chcesz go wypytać?', 'Porozmawiaj z Loraxem. Wysłuchaj, co ma do powiedzenia.$B', 'Wysłuchaj opowieści Loraxa', 'Wróć do Loraxa w Wąwozie Mrocznego Szeptu w Zimozdroju.', '', '', '', '', 0),
(5127, 'plPL', 'Demoniczna kuźnia', 'Lorax zawiera układy, nie przyjmuje ich od marnych śmiertelników.$B$BUkład jednak z tobą zawrę... weź tę pikę, jest przesycona potężną energią spaczenia. Gdy znajdziesz Goraluka Łamikowadło, zabij go i wbij tę pikę w jego zamierające serce. Swoją duszę przehandlował, jego duszę posiądę ja. Oddaj mi pikę i oddaj napierśnik, który ukradł złodziej, a nauczę cię tego, czego on miał się nauczyć.', 'Udaj się do Iglicy Czarnej Góry i odnajdź Goraluka Łamikowadło. Zabij go, a następnie użyj piki splamionej krwią na jego zwłokach. Gdy jego dusza zostanie wyssana, pika stanie się splamiona duszami.$B$BMusisz też znaleźć niewykuty napierśnik pokryty runami.$B$BZanieś pikę splamioną duszami i niewykuty napierśnik pokryty runami Loraxowi w Zimozdroju.', '', 'Wróć do Loraxa w Wąwozie Mrocznego Szeptu w Zimozdroju.', '', '', '', '', 0),
(5160, 'plPL', 'Matrona opiekunka', 'Wyrusz do Kalimdoru. Nasze stado ma swój dom w mroźnych krainach Zimozdroju. Gdy dotrzesz do Zimozdroju, odnajdź jaskinie Mazthoril.$B$BNa lodowej posadzce Mazthoril znajdziesz kobaltowe runy. Weź jedną z moich łusek i stań na runie, a runa przeniesie cię do Haleh, naszej matrony opiekunki.$B$BDaj jej łuskę, by mogła wywróżyć z niej to, co ujrzały moje oczy i co poczuło moje serce, tu, w tym skazanym na zgubę miejscu.', 'Wyrusz do Zimozdroju i odnajdź Haleh. Daj jej łuskę Awbee.', '', '', '', '', '', '', 0),
(5163, 'plPL', 'Daleko jeszcze, yeti?', 'Wszystko gotowe, $N!$B$BWysłałam już przyjaciołom list, że mam dla nich niespodziankę. I tu wkraczasz ty!$B$BDam ci mojego mechanicznego yeti, a ty zrobisz im niespodziankę: odwiedzisz każdego z moich przyjaciół, włączysz yeti i puścisz go w ich stronę.$B$BKiedy już pokażesz go Legacki w Wiecznowidzie, Sprinkle w Gadżetonie i Quixxilowi w Schronieniu Marshala, wróć i opowiedz mi, co się stało!$B$BI wtedy przynieś mi też z powrotem mojego yeti.', 'Weź mechanicznego yeti Umi i nastrasz nim jej przyjaciół:$B$BLegacki w Wiecznowidzie (Zimozdrój)$BSprinkle w Gadżetonie (Tanaris)$BQuixxila w Schronieniu Marshala (Krater Un\'Goro)$B$BKiedy skończysz, odnieś mechanicznego yeti Umi.', '', 'Wróć do Umi Rumplesnicker w Wiecznowidzie w Zimozdroju.', 'Nastrasz Legacki', 'Nastrasz Sprinkle', 'Nastrasz Quixxila', '', 0),
(5201, 'plPL', 'Najazdy Zimospadu', 'Większość nie zauważa mojej obecności, $N. Jest jednak pewna uciążliwość, która na dobre zadomowiła się w Zimozdroju: furbolgi z plemienia Zimospadu.$B$BChoć nigdy nie zaatakowałem furbolgów bezpośrednio, wydają się oszalałe i przestraszone wszystkim, co stanie im na drodze. Widziałem, jak zabijały niezliczone stworzenia, które miały pecha znaleźć się w złym miejscu o złym czasie.$B$BMam dość ich wtrącania się – proszę, pomóż mi, walcząc z nimi. Zabijaj furbolgi i trzymaj je z dala od Skały Mroźnych Szablobestii.', 'Rivern Mroźny Wiatr chce, abyś $gzabił:zabiła; 5 szamanów Zimospadu i 5 urs Zimospadu.', '', 'Wróć do Riverna Mroźnego Wiatru przy Skale Mroźnych Szablobestii w Zimozdroju.', '', '', '', '', 0),
(5244, 'plPL', 'Ruiny Kel\'Theril', 'Historia Kel\'Theril to opowieść o przeklętej rasie, przykutej do miejsca, w którym próbowała odprawić nieszczęsny rytuał...$B$BWysoko Urodzeni, których tam znajdziesz, ukradli niegdyś święty artefakt, wierząc, że zdołają wyssać z niego moc dla siebie i stać się jeszcze potężniejsi. W trakcie tych prób relikwia rozpadła się w potężnym wybuchu, a jej fragmenty trafiły pod lód jeziora...$B$BJeśli chcesz dowiedzieć się więcej, porozmawiaj z Jaronem Kamieniarzem. Niedawno odwiedził tę okolicę i powie ci więcej.', 'Porozmawiaj z Jaronem Kamieniarzem w Wiosce Spadającej Gwiazdy.', '', '', '', '', '', '', 0),
(5252, 'plPL', 'Skruszona Wysoko Urodzona', 'Kryształ... kryształ...$B$BWysoko Urodzonym tutaj własna niedoooola mąci zmysły...$B$BŻaaałuję, rozumiem błąąąd tego, co wydarzyło się tak dawno temu. Choć nie ma sposobuuu, by zmienić przeszłość, zaznałam spokoooju, wiedząc, że $godzyskałeś:odzyskałaś; kryształ Zin-Malor...$B$BMuuusisz go zwrócić...$B$BMuuusi zostać zwrrrócony.', 'Porozmawiaj z Wyndem Nocnym Pościgiem w Wiosce Spadającej Gwiazdy i zapytaj, gdzie jest właściwe miejsce dla Kryształu Zin-Malor.', '', '', '', '', '', '', 0),
(5305, 'plPL', 'Słodki Spokój', 'W murach Szkarłatnego Bastionu spoczywa słodki Spokój. Karmazynowy mistrz młotów strzeże jego przepisu własnym życiem. Pokonaj go i przynieś mi jego fartuch. W zamian nagrodzę cię wiedzą potrzebną do wykucia zaklętego młota bojowego!', 'Udaj się do Stratholmu i zabij karmazynowego mistrza młotów. Zdobądź fartuch karmazynowego mistrza młotów i wróć do Lilith.$B', '', 'Wróć do Lilith Zwinnej w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5306, 'plPL', 'Wężowy kamień Łowczyni Cieni', 'Nie daj się zwieść jej urodzie, $N. Łowczyni Cieni Vosh\'gajin jest zabójcza i obłąkana.$B$B<Kilram wskazuje na bliznę na swojej twarzy.>$B$BTak, to jej dzieło – czułe klepnięcie, jak to nazwała.$B$BWreszcie nadszedł czas zemsty.$B$BVosh\'gajin znajdziesz w Iglicy Czarnej Góry. Zabij ją i wróć do mnie z jej wężowym kamieniem. Zrób to, a zdradzę ci sekret wykuwania Ostrza świtu!', 'Udaj się do Iglicy Czarnej Góry i zabij Łowczynię Cieni Vosh\'gajin. Zdobądź wężowy kamień Vosh\'gajin i wróć do Kilrama.', '', 'Wróć do Kilrama w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5307, 'plPL', 'Splugawienie', 'Jeśli jestem dla ciebie oschły, to nie bez powodu. Plany wykucia wielkiego ostrza, Splugawienia, zostały skradzione przez Czarną Straż: elitarne oddziały szkieletów barona Zerwikrusza.$B$BTak, barona Zerwikrusza ze Stratholmu.$B$BMiecznik Czarnej Straży strzeże teraz tych planów swoim... nieżyciem.$B$BZabij go i przynieś dowód tego czynu, a dam ci wiedzę potrzebną do wykucia płonącego rapiera!', 'Znajdź miecznika Czarnej Straży w Stratholmie i zniszcz go. Zdobądź Insygnium Czarnej Straży i wróć do Serila Zguby Plagi.', '', 'Wróć do Serila Zguby Plagi w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0),
(5981, 'plPL', 'Szalejące olbrzymy', 'Około 4000 lat temu Tyrande Szept Wiatru ocaliła życie królowej mroźnych szablobestii, której zagrażały szalejące olbrzymy. Od tamtej pory mroźne szablobestie są sojusznikami nocnych elfów.$B$BTe same olbrzymy, które niegdyś zagrażały mroźnym szablobestiom, wciąż żyją niedaleko stąd. Zwą się Mroźnymi Maczugami i zajęły wielką dolinę na południu.$B$BUdowodnij swoją lojalność wobec mroźnych szablobestii – zabij te olbrzymy w imię królowej mroźnych szablobestii, Shy-Rotam!', 'Rivern Mroźny Wiatr chce, abyś $gzabił:zabiła; 4 olbrzymy Mroźnych Maczug i 4 opiekunów Mroźnych Maczug.', '', 'Wróć do Riverna Mroźnego Wiatru przy Skale Mroźnych Szablobestii w Zimozdroju.', '', '', '', '', 0),
(6603, 'plPL', 'Kłopoty w Zimozdroju!', 'W Zimozdroju są kłopoty!$B$BA jakże, spędzam trochę czasu na łonie natury i znam się na tych sprawach... zawsze mówię to z wielką dumą. Godziny spędzone tam, na wzgórzach, są dla mnie na wagę złota. Pomagają wyrobić sobie szybki refleks, chłodną głowę i bystre oko...$B$BTrzeba rozsądku, rozumu i dojrzałości, żeby docenić dziką przyrodę tak jak ja.$B$BTo o czym ja mówiłam?$B$BAch tak, kłopoty. Odwiedź Donovę Snowden przy gorących źródłach, ona powie ci więcej.$B$B', 'Znajdź Donovę Snowden przy gorących źródłach w Zimozdroju.', '', '', '', '', '', '', 0),
(6604, 'plPL', 'Rozwścieczone dziczołaki', '$GWidziałeś:Widziałaś; ten opuszczony obóz na południe stąd? Wygląda na to, że dziczołaki oszalały i zniszczyły niemal wszystko, co wpadło im w łapy!$B$BSłyszałem plotkę, że jeden z tych, którzy przeżyli atak, odpoczywa w Wiosce Spadającej Gwiazdy, na zachód stąd. Jestem naprawdę ciekaw, co się stało... a ty nie?', 'Porozmawiaj z Jaronem Kamieniarzem w Wiosce Spadającej Gwiazdy.', '', '', '', '', '', '', 0),
(6606, 'plPL', 'Odrobina szczęścia', 'Odrobina szczęścia zawsze się przyda, co? Wystarczy niewielka przewaga, żeby odwrócić sytuację na swoją korzyść...$B$BJakiś czas temu poznałem dość ekscentryczną znachorkę. Zrobiła mi amulet na szczęście... za odpowiednią cenę. Ale wierz mi, było warto!$B$BMoże chcesz mieć własny? Znajdź znachorkę Mau\'ari w Wiecznowidzie. Swojego nie oddam!', 'Porozmawiaj ze znachorką Mau\'ari w Wiecznowidzie.', '', '', '', '', '', '', 0),
(8672, 'plPL', 'Nestor Kamienna Iglica', '', '', '', '', '', '', '', '', 0),
(8726, 'plPL', 'Nestor Jasna Włócznia', '', '', '', '', '', '', '', '', 0),
(8798, 'plPL', 'Twój własny yeti', '', '', '', '', '', '', '', '', 0),
(8869, 'plPL', 'Słodki Spokój', '', 'Udaj się do Stratholmu i zabij karmazynowego mistrza młotów. Zdobądź fartuch karmazynowego mistrza młotów i wróć do Lilith.$B', '', 'Wróć do Lilith Zwinnej w Wiecznowidzie w Zimozdroju.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(969, 'plPL', 'Aaach, tak... Zaraz zrobię dla ciebie ten amulet. Tylko poczekaj!', 0),
(975, 'plPL', 'Proszę, $N. Pamiętaj, musisz go nosić przy sobie. Może wrócisz do Zimozdroju i zobaczysz, co tam znajdziesz?', 0),
(977, 'plPL', 'Nie mogę się doczekać, aż pokażę to przyjaciołom! Teraz chwileczkę, tylko je przymocuję...$b$bIdealnie!', 0),
(3783, 'plPL', 'Te futra są idealne, $N. Świetnie zaczynamy!', 0),
(4801, 'plPL', 'Mau\'ari może wydobyć juju dla ciebie, $N... Użyj Skrytki Mau\'ari, aby rzucić je na siebie albo swoich sojuszników.', 0),
(4802, 'plPL', 'Mau\'ari może wydobyć juju dla ciebie, $N... Użyj Skrytki Mau\'ari, aby rzucić je na siebie albo swoich sojuszników.', 0),
(4803, 'plPL', 'Mau\'ari może wydobyć juju dla ciebie, $N... Użyj Skrytki Mau\'ari, aby rzucić je na siebie albo swoich sojuszników.', 0),
(4804, 'plPL', 'Mau\'ari może wydobyć juju dla ciebie, $N... Użyj Skrytki Mau\'ari, aby rzucić je na siebie albo swoich sojuszników.', 0),
(4805, 'plPL', 'Mau\'ari może wydobyć juju dla ciebie, $N... Użyj Skrytki Mau\'ari, aby rzucić je na siebie albo swoich sojuszników.', 0),
(4806, 'plPL', 'Mau\'ari może wydobyć juju dla ciebie, $N... Użyj Skrytki Mau\'ari, aby rzucić je na siebie albo swoich sojuszników.', 0),
(4807, 'plPL', 'Mau\'ari może wydobyć juju dla ciebie, $N... Użyj Skrytki Mau\'ari, aby rzucić je na siebie albo swoich sojuszników.', 0),
(4809, 'plPL', 'To dobre okazy. Aż buchają zimnem! Tylko założę rękawice, a potem zapakuję je razem z resztą rzeczy, których potrzebuje Tinkee...', 0),
(4842, 'plPL', 'Tak, demony w Wąwozie Mrocznego Szeptu – uważam, że to ich obecność tak wpływa na tę ziemię. Zamierzam dalej obserwować tutejsze gorące źródła i zobaczyć, czy dowiem się czegoś więcej.$b$bJeśli planujesz zapuścić się dalej w Wąwóz Mrocznego Szeptu, poczekałabym, aż trochę się wzmocnisz.', 0),
(4861, 'plPL', 'Wśród zniszczonego dobytku w obozie wyróżnia się mocno uszkodzona skrzynia...', 0),
(4863, 'plPL', 'Po podejściu do wozu widać, że nie ma tu już wiele rzeczy dla Jarona. Na ziemi zauważasz jednak kilka skrzyń, które mimo że są do połowy zasypane śniegiem, wyglądają na nieuszkodzone.', 0),
(4864, 'plPL', 'Cóż, spodziewałem się tego, $gchłopcze:dziewczyno;. Domyślałem się, że te oszalałe bestie zniszczyły cały mój dobytek...$B$BAle $gznalazłeś:znalazłaś; moje narzędzia i, co najważniejsze, amulet! Ciekawe, czemu dziczołaki tak zaciekle go broniły... Tak czy inaczej, dwa razy się zastanowię, zanim znów pójdę w ich stronę!', 0),
(4970, 'plPL', 'Dziękuję za pomoc, $N. Z czasem mam o tobie coraz lepsze zdanie.', 0),
(5047, 'plPL', 'Żyje? Kombinezon zadziałał? A co my tu mamy?', 0),
(5054, 'plPL', 'To nie było łatwe zadanie, a jednak $gspisałeś:spisałaś; się znakomicie. Ale nie myśl zbyt pochopnie, że $gzrobiłeś:zrobiłaś; na mnie wrażenie, $N.', 0),
(5055, 'plPL', 'Tak. $GWróciłeś:Wróciłaś;. Teraz wierzę, że masz to we krwi. $GStawiłeś:Stawiłaś; czoła najdzikszym stworzeniom i $gwróciłeś:wróciłaś;, przerastając moje oczekiwania.$b$bJesteś $ggotów:gotowa; na moją ostatnią prośbę.', 0),
(5056, 'plPL', '$GUdowodniłeś:Udowodniłaś; zarówno swoją siłę, jak i determinację. Czeka cię jeszcze wiele wyzwań, ale pokazałem ci już wszystko, co mogłem.$b$bPowodzenia, $N.', 0),
(5057, 'plPL', 'Uczymy się z tego, czego doświadczamy w życiu, $N. Jestem pewien, że dzięki swoim doświadczeniom $gstałeś:stałaś; się tylko $gsilniejszy i mądrzejszy:silniejsza i mądrzejsza;. Bardzo $gdorosłeś:dorosłaś; od naszej pierwszej rozmowy.$b$bWeź to na pamiątkę trudnych zadań, których $gdokonałeś:dokonałaś; jako $R $C, i wiedz, że zawsze będziesz mieć mój szacunek i podziw.', 0),
(5063, 'plPL', 'Zdumiewające! Zebranie tych składników musiało zająć całe tygodnie... i skąd $gwziąłeś:wzięłaś; nieskazitelną skórę?!?$b$bCiesz się czapką, $N!', 0),
(5067, 'plPL', 'Rzadko widziałem, by śmiertelnicy dokonali rzeczy bardziej nieprawdopodobnej. Napawaj się chwałą mego dzieła! Zbieraj jego owoce!', 0),
(5068, 'plPL', 'Myślałem, że prędzej umrę i zostanę pogrzebany, niż doczekam tego dnia.$B$BTak wielkie osiągnięcie może przyćmić tylko nagroda.', 0),
(5082, 'plPL', 'Bardzo dziękuję, $N! Teraz mogę wrócić do pracy.$B$B$GZnalazłeś:Znalazłaś; coś ciekawego w obozie Zimospadu?', 0),
(5083, 'plPL', 'Masz to od furbolgów z Zimospadu?', 0),
(5086, 'plPL', 'Muszę porównać to z substancją, którą $gznalazłeś:znalazłaś; w kotle, a wtedy na pewno dowiemy się więcej.', 0),
(5087, 'plPL', '<Donova bada zawartość skrzyni.>$b$bCiekawe, czy spożywanie tej substancji czyni furbolgi bardziej agresywnymi. Rzeczywiście wydają się znacznie większe...', 0),
(5103, 'plPL', 'Co do...', 0),
(5121, 'plPL', 'Bardzo ci dziękuję, $N. Mam nadzieję, że wrócę do swoich badań bez obawy, że ktoś zaatakuje mnie z zasadzki. Przyjmij to w nagrodę.', 0),
(5123, 'plPL', 'Ciekawe, co to wszystko znaczy... Nic nie mogę z tego wyczytać...', 0),
(5124, 'plPL', 'Jak obiecałem, $N, oto twój przepis! Dorzucę też coś ekstra za całą twoją ciężką pracę i poświęcenie. I tak co ja miałbym z tym robić???', 0),
(5126, 'plPL', '<Lorax się śmieje.>', 0),
(5127, 'plPL', 'Paktu nie złamano. Duszę mi oddano. Nagrodę przygotowano.', 0),
(5160, 'plPL', 'Aspekty nalegają, byśmy trzymali się z dala od spraw śmiertelników. Na tym świecie nie zawsze jest to jednak możliwe – zwłaszcza gdy ktoś z naszych z pogardą lekceważy takie nakazy.', 0),
(5161, 'plPL', 'Niech tak będzie...', 0),
(5163, 'plPL', 'Ha! Zastanowią się dwa razy, zanim znów zaczną się śmiać z moich pomysłów!$B$BDzięki za pomoc, $N. Bez ciebie nie byłoby tyle zabawy!', 0),
(5201, 'plPL', 'Z ulgą słyszę, że choć przez krótką chwilę nie będziemy musieli martwić się najazdami Zimospadu.$B$BZaczynasz pokazywać swoją wytrwałość, $N.', 0),
(5244, 'plPL', 'No pewnie, mogę ci opowiedzieć więcej o Kel\'Theril. Tylko pamiętaj, nie jestem żadnym historykiem, ale mogę ci powiedzieć, co tam widziałem...', 0),
(5252, 'plPL', 'Czy to... jest to, co myślę?', 0),
(5305, 'plPL', 'Obyś $grozbił:rozbiła; jeszcze wiele łbów, $N!', 0),
(5306, 'plPL', 'Wiedza to potęga!', 0),
(5307, 'plPL', 'Powinno być oczywiste, że miecz to zawsze najlepszy wybór.', 0),
(5981, 'plPL', 'Doskonale, $N. Twoja determinacja została należycie odnotowana.', 0),
(6603, 'plPL', 'No, cześć! Czyli Meggi opowiedziała ci o kłopotach, na które tu trafiłam?', 0),
(6604, 'plPL', 'Tak, co mogę dla ciebie zrobić?', 0),
(6606, 'plPL', 'Ach, to Harlo cię przysyła? No, to kim ty jesteś? Pewnie chcesz mojej pomocy?', 0),
(8549, 'plPL', 'To nie było łatwe zadanie, a jednak $gspisałeś:spisałaś; się znakomicie. Ale nie myśl zbyt pochopnie, że $gzrobiłeś:zrobiłaś; na mnie wrażenie, $N.', 0),
(8798, 'plPL', 'Ej! Wiesz co?! Też jesteś $ginżynierem:inżynierką;! Skoro $gpomogłeś:pomogłaś; mi dać nauczkę przyjaciołom, nauczę cię, jak zbudować własnego mechanicznego yeti! Teraz zabawa może trwać wiecznie, a ty możesz straszyć, kogo tylko zechcesz! O ile oczywiście zdołasz gdzieś wytrzasnąć potrzebne części.$B$BCo ty na to, $N? Chcesz poznać sekret budowy mechanicznego yeti?', 0),
(11763, 'plPL', 'Zbezcześć wielkie ognisko Przymierza w Zimozdroju!', 0),
(11803, 'plPL', 'Zbezcześć wielkie ognisko Hordy w Zimozdroju!', 0),
(11834, 'plPL', 'Uczcij płomień Zimozdroju!', 0),
(11839, 'plPL', 'Uczcij płomień Zimozdroju!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(969, 'plPL', 'Przynieś odłamki, a powiem ci więcej!', 0),
(977, 'plPL', 'Prawie skończyłam przyczepiać futro, $N. Proszę, pospiesz się z tymi rogami!', 0),
(3783, 'plPL', 'Mam tu mnóstwo roboty na start. Proszę, przynieś mi te futra najszybciej, jak możesz!', 0),
(4801, 'plPL', 'W Zimozdroju będziesz walczyć z wielkimi kotami zwanymi mroźnymi szablobestiami. Te bestie są niesamowicie szybkie i przebiegłe. Jeśli chcesz zyskać szybkość mroźnej szablobestii, przynieś mi e\'ko, które od nich zdobędziesz.$B$BPamiętaj, musisz mieć Skrytkę Mau\'ari w swoim ekwipunku, jeśli chcesz polować na e\'ko.', 0),
(4802, 'plPL', 'W Zimozdroju będziesz walczyć z zabłąkanymi stworzeniami, znanymi jako furbolgi z plemienia Zimospadu. Z woli swojego przywódcy zyskały niesamowitą siłę. Jeśli chcesz zyskać moc Zimospadu, przynieś mi e\'ko, które od nich zdobędziesz.$B$BPamiętaj, musisz mieć Skrytkę Mau\'ari w swoim ekwipunku, jeśli chcesz polować na e\'ko.', 0),
(4803, 'plPL', 'W Zimozdroju spotkasz wielkie niedźwiedzie o niezwykle grubej skórze. Te skałozębne niedźwiedzie są dobrze chronione, bo wiele potrafią wytrzymać. Jeśli chcesz zyskać odporność na ogień, przynieś mi e\'ko, które zdobędziesz od skałozębnych.$B$BPamiętaj, musisz mieć Skrytkę Mau\'ari w swoim ekwipunku, jeśli chcesz polować na e\'ko.$B$B', 0),
(4804, 'plPL', 'W Zimozdroju będziesz walczyć z wielkimi latającymi stworzeniami zwanymi chimerami z Zimnych Wichrów. Te bestie władają magią mrozu. Jeśli chcesz zyskać odporność na mróz, przynieś mi e\'ko, które od nich zdobędziesz.$B$BPamiętaj, musisz mieć Skrytkę Mau\'ari w swoim ekwipunku, jeśli chcesz polować na e\'ko.$B$B', 0),
(4805, 'plPL', 'W Zimozdroju będziesz walczyć z wielkimi stworzeniami zwanymi yeti Lodowego Ostu. Te bestie poruszają się powoli, ale dzięki ochronie grubego futra potrafią uniknąć wielu ciosów. Jeśli chcesz zyskać umiejętność unikania ataków, przynieś mi e\'ko, które od nich zdobędziesz.$B$BPamiętaj, musisz mieć Skrytkę Mau\'ari w swoim ekwipunku, jeśli chcesz polować na e\'ko.$B$B', 0),
(4806, 'plPL', 'W Zimozdroju $gwalczyłeś:walczyłaś; już z wielkimi lodowymi olbrzymami zwanymi Mroźnymi Maczugami. Mają do dyspozycji czystą siłę i moc. Jeśli chcesz zyskać siłę Mroźnych Maczug, przynieś mi e\'ko, które od nich zdobędziesz.$B$BPamiętaj, musisz mieć Skrytkę Mau\'ari w swoim ekwipunku, jeśli chcesz polować na e\'ko.', 0),
(4807, 'plPL', 'W Zimozdroju będziesz walczyć z potężnymi stworzeniami, które zdają się mieć wrodzony dar magii. Te dziczołaki potrafią używać silnej magii. Jeśli chcesz zwiększyć swój intelekt, przynieś mi e\'ko, które zdobędziesz od któregoś z tamtejszych sowostworów.$B$BPamiętaj, musisz mieć Skrytkę Mau\'ari w swoim ekwipunku, jeśli chcesz polować na e\'ko.$B$B', 0),
(4809, 'plPL', 'Masz rogi chimer, $N?', 0),
(4842, 'plPL', 'Woda w źródłach wydaje się mieć bardzo dziwne właściwości... Wciąż nie wiem, co to oznacza...', 0),
(4864, 'plPL', 'Tak... Opowiadaj, co słychać.', 0),
(4970, 'plPL', 'Dyscyplina i determinacja – to twoje cele. Mogę wiele razy prosić cię o to samo proste zadanie. Za każdym razem musisz wykonać je najlepiej, jak potrafisz.', 0),
(5047, 'plPL', 'Tak?', 0),
(5054, 'plPL', 'Idź już, $N. Odszukaj Ursiusa.', 0),
(5055, 'plPL', 'Brumeran cię wzywa, $N.', 0),
(5056, 'plPL', 'Shy-Rotam jest śmiała i bezlitosna. Będzie bronić swojego rodzaju z żarliwym zapałem.', 0),
(5063, 'plPL', 'Jeśli nie masz wszystkiego, czego potrzebuję, marnujesz mój czas.', 0),
(5067, 'plPL', 'Jeśli nie masz wszystkiego, czego potrzebuję, marnujesz mój czas.', 0),
(5068, 'plPL', 'Jeśli nie masz wszystkiego, czego potrzebuję, marnujesz mój czas.', 0),
(5082, 'plPL', 'Dziękuję za pomoc!', 0),
(5083, 'plPL', 'Co takiego $gznalazłeś:znalazłaś;?', 0),
(5086, 'plPL', 'Chyba zaczynamy odkrywać, co się tu dzieje, $N.', 0),
(5087, 'plPL', 'Zobaczymy, co się stanie, kiedy furbolgi z Zimospadu nie dostaną swojej ognistej wody!', 0),
(5121, 'plPL', 'Może w Wiosce Zimospadu dowiesz się czegoś więcej, $N.', 0),
(5123, 'plPL', 'Co to takiego, $N?', 0),
(5124, 'plPL', 'Czas to pieniądz, $N, a ja nie mam za dużo ani jednego, ani drugiego.', 0),
(5127, 'plPL', 'Nie kuś...', 0),
(5160, 'plPL', 'Dobrze cię widzieć, $N.', 0),
(5163, 'plPL', 'Nie mogę się doczekać, aż usłyszę, jak zareagowali moi przyjaciele!$B$BNigdy się tego nie spodziewają!', 0),
(5201, 'plPL', 'Te furbolgi zdają się cierpieć na straszną paranoję...', 0),
(5252, 'plPL', 'Minęło trochę czasu, odkąd $godszedłeś:odeszłaś;, $N. Jak ci się wiodło?', 0),
(5305, 'plPL', 'Jego fartuch! Gdzie on jest?', 0),
(5306, 'plPL', 'Legenda głosi, że jedno użycie wężowego kamienia Vosh\'gajin utrzyma topór ostry jak brzytwa przez 1000 lat!', 0),
(5307, 'plPL', 'Czyżbyś $gzapomniał:zapomniała;, co ci zlecono, $N?', 0),
(5981, 'plPL', 'Musisz dalej się wykazywać, $N.', 0);
