INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(5659, 'plPL', '', 'Ach... Mam wielką wiedzę o świecie i o tym, jak tworzyć amulety o wielkiej mocy.', 0),
(5661, 'plPL', '', 'Mau\'ari wie, czemu jej szukasz...$B$BPrzynieś mi e\'ko, które znajdziesz w świecie, a ja je dla ciebie przemienię.', 0),
(5662, 'plPL', 'Jak używać Skrytki Mau\'ari?', 'Jak używać Skrytki Mau\'ari?', 0),
(5698, 'plPL', 'Co to jest e\'ko?', 'Co to jest e\'ko?', 0),
(5699, 'plPL', '', 'Skrytka Mau\'ari kryje wielkie tajemnice... Odłamki, z których ją zrobiono, odbijają światło, a jej lśniącą powierzchnią możesz wysysać moc z innych rzeczy i odbijać ją na siebie.$B$BGdy nosisz amulet w swoim ekwipunku, możesz zbierać e\'ko – duchową moc bestii, z którymi walczysz. Gdy znajdziesz e\'ko, przynieś je do Mau\'ari.', 0),
(5700, 'plPL', '', 'E\'ko to moc, którą posiada każde stworzenie. Amulet, który ci zrobiłam, pozwala ci ją pochwycić w materialnej postaci.$B$BZnam zaklęcie, które potrafi przemienić znalezione przez ciebie e\'ko w juju.$B$BPotem możesz wziąć Skrytkę Mau\'ari i użyć jej, by odbić moc juju na siebie.$B$BNo dalej, spróbuj. Przynieś e\'ko do Mau\'ari, a zabawimy się.', 0),
(5756, 'plPL', 'Co to jest juju?', 'Co to jest juju?', 0),
(5758, 'plPL', '$GZgubiłem:Zgubiłam; Skrytkę Mau\'ari. Co mogę zrobić?', '$GZgubiłem:Zgubiłam; Skrytkę Mau\'ari. Co mogę zrobić?', 0),
(6039, 'plPL', '', '%s ryczy, wzywając swojego partnera!', 0),
(6066, 'plPL', 'Skaczące trędowate gnomy! Tkwiłem tam całe miesiące. Dzięki, ekipo.', '', 0),
(6078, 'plPL', 'Uff... Potrzebuję fajki i dotyku pięknej gnomki – niekoniecznie w tej kolejności!$B$BCałe miesiące tkwiłem w brzuchu tego stwora! Który to w ogóle dzień? Ach, nieważne. Liczy się tylko to, że w końcu jestem na wolności.$B$BJUHUUU!', '', 0),
(6079, 'plPL', 'Jak do diabła w ogóle się tam dostałeś?\n', 'Jak do diabła w ogóle się tam dostałeś?\n', 0),
(6080, 'plPL', 'Jak?? No cóż, to długa historia.', '', 0),
(6082, 'plPL', 'No dobra! Byłem sobie przy jeziorach lawy przy Stopionym Moście i testowałem swój kombinezon do lawy. Wszystko szło świetnie. Mogłem nawet pływać w tym świństwie bez najmniejszego uszczerbku!$B$BNo więc jestem sobie, nikomu nie wadzę, robię parę długości na plecach, a tu nagle znikąd ten stwór połyka mnie w całości! Gdyby nie mój kombinezon i wbudowany podajnik granulek pokarmowych, byłoby po mnie!', '', 0),
(6083, 'plPL', 'Niech no się upewnię. Pływałeś, ba, pływałeś na plecach w roztopionej lawie w tym... tym swoim kombinezonie do lawy? Tak? I nagle znikąd ta bestia połknęła cię w całości?', 'Niech no się upewnię. Pływałeś, ba, pływałeś na plecach w roztopionej lawie w tym... tym swoim kombinezonie do lawy? Tak? I nagle znikąd ta bestia połknęła cię w całości?', 0),
(6084, 'plPL', 'Hej, wyczuwam w twoim głosie nutkę niedowierzania – ale tak, właśnie tak to było.', '', 0),
(6085, 'plPL', 'Muszę coś wiedzieć: jak chodziłeś do toalety w tym stroju?', 'Muszę coś wiedzieć: jak chodziłeś do toalety w tym stroju?', 0),
(6086, 'plPL', 'Nie minęły nawet dwie minuty, odkąd wyszedłem z brzucha tej bestii, a ktoś już pyta mnie o toaletowe zwyczaje??? $GPanie:Panienko;, gdyby nie to, że to ty mnie $guratowałeś:uratowałaś;, za takie pytanie $gdostałbyś:dostałabyś; ode mnie po uszach!$B$BW każdym razie jestem wdzięczny za pomoc. Może jakoś ci się odwdzięczę?', '', 0),
(6087, 'plPL', 'Tak?', 'Tak?', 0),
(6088, 'plPL', 'No, może „odwdzięczę” to nie najlepsze słowo. Widzisz, kiedy tkwiłem w brzuchu tego stwora, zacząłem się zastanawiać:$B$BTo stworzenie żyje w gorącej, płonącej magmie, a mimo to ogień nie robi mu najmniejszej krzywdy!$B$BGdybym tylko mógł zdobyć nieskazitelną skórę jednej z tych bestii. Mógłbym zanieść ją mojemu drogiemu przyjacielowi, Malyfousowi Mrocznemu Młotowi, do Wiecznowidu. Jeśli ktokolwiek potrafi coś zrobić ze skóry takiej bestii, to właśnie on. \n', '', 0),
(6090, 'plPL', 'Może więc zaniesiesz ode mnie wiadomość?', '', 0),
(6092, 'plPL', 'Do Malyfousa, jak się domyślam.', 'Do Malyfousa, jak się domyślam.', 0),
(6101, 'plPL', '%s skomli.', '', 0),
(6128, 'plPL', 'Bractwo Torium nie marnuje czasu na mrówki. Precz!', '', 0),
(6129, 'plPL', 'Opowiedz mi o skórze.', 'Opowiedz mi o skórze.', 0),
(6130, 'plPL', 'Dla rzemieślnika mojego kalibru to prosta sprawa.$B$BNajtrudniejsze w wytwarzaniu przedmiotów ze skór i pancerzy bestii jest samo zdobycie tych części. Gdybyś $gprzyniósł:przyniosła; mi nieskazitelną skórę tej bestii, mógłbym zrobić z niej kilka różnych potężnych przedmiotów.', '', 0),
(6131, 'plPL', 'Jakie są szanse na zdobycie takiej skóry?', 'Jakie są szanse na zdobycie takiej skóry?', 0),
(6132, 'plPL', 'Myślę, że szansa na zdobycie takiego kawałka to jeden do miliona! Taka skóra trafia się raz w życiu! Nawet najbardziej zdyscyplinowani mistrzowie tego rzemiosła bez wątpienia zawiedliby kilkaset razy przy oprawianiu bestii, zanim zdobyliby nieskazitelny okaz.\n', '', 0),
(6133, 'plPL', 'Załóżmy, że zdobędę tę skórę. Czego jeszcze byś potrzebował i co właściwie mógłbyś zrobić?', 'Załóżmy, że zdobędę tę skórę. Czego jeszcze byś potrzebował i co właściwie mógłbyś zrobić?', 0),
(6134, 'plPL', 'Gdybyś naprawdę $gprzyniósł:przyniosła; mi skórę tej bestii? No cóż... Pokażę ci...', '', 0),
(6135, 'plPL', 'Dobra!', 'Dobra!', 0),
(6139, 'plPL', 'Przejrzyj mój katalog, $n.', '', 0),
(6144, 'plPL', 'Jesienny katalog Bractwa Torium:$B$BW środku znajdziesz najgorętsze oferty na wszystko, czego potrzebujesz na wyprawy! Pokażemy ci nawet, gdzie zdobyć trudno dostępne składniki i zapasy.', '', 0),
(6145, 'plPL', 'Rozdział o postrzępionych szwach plugastwa.', 'Rozdział o postrzępionych szwach plugastwa.', 0),
(6146, 'plPL', 'Rozdział o zaczarowanej szkarłatnej nici.', 'Rozdział o zaczarowanej szkarłatnej nici.', 0),
(6147, 'plPL', 'Rozdział o płynie do balsamowania Reza Szepta Mrozu.', 'Rozdział o płynie do balsamowania Reza Szepta Mrozu.', 0),
(6151, 'plPL', 'Rozdział o tajemnych kryształach i arkanicie.', 'Rozdział o tajemnych kryształach i arkanicie.', 0),
(6161, 'plPL', 'Rozdział o skórze cienia.', 'Rozdział o skórze cienia.', 0),
(6163, 'plPL', 'Jeśli szwów plugastwa potrzebujesz, do Stratholmu wędrujesz.$B$BNiegdyś rodzinne miasto samego Światłodzierżcy, dziś opanowane przez sługi Kel\'Thuzada.$B$BStaw czoła niebezpieczeństwom płonącego miasta i powal mięsiste plugastwa! Weź od nich swoją nagrodę: postrzępione szwy plugastwa!', '', 0),
(6164, 'plPL', 'Ostatnie sanktuarium oszalałych fanatyków. To tam szyją swoje szkarłatne mundury, nasycone magią zaczarowanej szkarłatnej nici!$B$BDo Stratholmu, poszukiwaczu przygód!', '', 0),
(6165, 'plPL', 'Najlepszy środek do konserwacji ciała, znany zarówno ludziom, jak i Pladze – płyn do balsamowania Reza Szepta Mrozu. Jest tylko jedno miejsce, gdzie poszukiwacz przygód może go znaleźć, a można przypuszczać, że lisz, od którego płyn wziął nazwę, nie przyjmie życzliwie nikogo, kto się tam wybierze.$B$BAle... jeśli po płyn się wybierasz, do Scholomancjum zmierzasz...', '', 0),
(6166, 'plPL', 'Ziemię, na której zbudowano Scholomancjum, oddał Kel\'Thuzadowi ród Barovów. W zamian za tę ziemię – miejsce, gdzie Kult Potępionych mógł zgłębiać plugawą magię Plagi – Kel\'Thuzad obdarzył Barovów nieśmiertelnością w nieżyciu.$B$BTo w Cienistej Krypcie znajdziesz zarówno skórę cienia, jak i jej właścicielkę, lady Illucię Barov.$B$BNigdy nie było piękniejszego zwierciadła dla próżnych i martwych.', '', 0),
(6167, 'plPL', 'Podstawa działalności Bractwa Torium.$B$BKryształy arkanitu wydobywa się z bogatych żył torium. Dzięki kunsztowi potężnych alchemików rodzą się z nich sztabki arkanitu.$B$BJeśli nie jesteś górnikiem, poszukaj górnika... i znajdź dobrego alchemika! Będziesz potrzebować obu.', '', 0),
(6240, 'plPL', 'Nie wystawiaj mojej cierpliwości na próbę, $gśmiertelniku:śmiertelniczko;.', '', 0),
(6241, 'plPL', 'Wybacz, Loraksie, ale nie mówię w języku szaleńców.', 'Wybacz, Loraksie, ale nie mówię w języku szaleńców.', 0),
(6242, 'plPL', 'Ugryź się w język, $gśmiertelniku:śmiertelniczko;, zanim wyrwę ci go z czaszki i zrobię z niego ogrzewacz do rogów.', '', 0),
(6243, 'plPL', 'Przepraszam, nie $gwiedziałem:wiedziałam;, że rozumiesz, co mówię. Co tu robisz?', 'Przepraszam, nie $gwiedziałem:wiedziałam;, że rozumiesz, co mówię. Co tu robisz?', 0),
(6244, 'plPL', 'To, co robię zawsze, rzecz jasna. Rozmyślam ponuro. Lamentuję. Nienawidzę. Knuję. Gdy ten cykl się dopełni, znów rozmyślam ponuro. Czego ode mnie chcesz? Mam wiele na głowie.', '', 0),
(6245, 'plPL', 'Doprawdy? Może powinieneś mi powiedzieć, co cię gnębi.', 'Doprawdy? Może powinieneś mi powiedzieć, co cię gnębi.', 0),
(6246, 'plPL', 'Ty?$B$B<Lorax się śmieje.>$B$BWątpliwe.$B$BStoję pośród tych ruin i śnię. Śnię o dniu, w którym dopadnę tego nędznego złodzieja, Goraluka Łamikowadło.$B$BZawarliśmy układ, on i ja. Układ, który złamał. Zdradził.', '', 0),
(6247, 'plPL', 'Jaki układ?', 'Jaki układ?', 0),
(6248, 'plPL', 'Miałem nauczyć go demonicznego kowalstwa w zamian za jego duszę. Dusza orka z Czarnej Skały jest niewiele warta, ale w tych trudnych czasach dusza, jakakolwiek dusza, jest lepsza niż żadna.', '', 0),
(6249, 'plPL', 'Jak więc złamał układ?', 'Jak więc złamał układ?', 0),
(6250, 'plPL', 'Zabrał niewykuty napierśnik pokryty runami, potrzebny do wykonania napierśnika wykutego przez demony, i uciekł, nie płacąc. Głupcem jednak nie jestem... niewykuty napierśnik jest bezużyteczny bez wiedzy albo przepisu, jak tę wiedzę zastosować.$B$BCiekawe... czy siedzi bezpiecznie w swoim mieście, Iglicy Czarnej Góry, i próbuje wykonać przedmiot z surowego materiału? Wiem, że nie odważy się stamtąd wyjść!\n', '', 0),
(6251, 'plPL', 'Może $gmógłbym:mogłabym; pomóc. Zawrę z tobą układ, satyrze. Odzyskam ten niewykuty napierśnik i zabiję tę bestię, Goraluka Łamikowadło. W zamian za to zadanie nauczysz mnie, jak wykonać napierśnik.', 'Może $gmógłbym:mogłabym; pomóc. Zawrę z tobą układ, satyrze. Odzyskam ten niewykuty napierśnik i zabiję tę bestię, Goraluka Łamikowadło. W zamian za to zadanie nauczysz mnie, jak wykonać napierśnik.', 0),
(6270, 'plPL', '%s skomli.', '', 0),
(6271, 'plPL', '%s oddycha nierówno.', '', 0),
(6272, 'plPL', '%s woła o pomoc.', '', 0),
(6273, 'plPL', 'Moje... moje rany są ciężkie...', '', 0),
(6275, 'plPL', 'Wszystko będzie dobrze, Awbee. Twoi napastnicy zostali zlikwidowani.', 'Wszystko będzie dobrze, Awbee. Twoi napastnicy zostali zlikwidowani.', 0),
(6276, 'plPL', 'Słuchaj, śmiertelna istoto. Słuchaj uważnie...$B$BSmoczy jeźdźcy przybyli nocą na grzbietach Czarnego Stada. Uderzyli szybko i ze śmiercionośną precyzją, porwali młode smoczęta – takie jak ja – i uciekli pod osłoną ciemności.$B$BNa moich oczach, ku mojej zgrozie, wykorzystywali moich braci i siostry w swoich eksperymentach. Z naszej esencji miało powstać Chromatyczne Stado.', '', 0),
(6277, 'plPL', 'Mów dalej, proszę...', 'Mów dalej, proszę...', 0),
(6278, 'plPL', 'Nefarian rozkazał natychmiast niszczyć nieprzydatne okazy, ale te nikczemne bestie nie robiły tego, zanim nie zadały „wystarczająco” dużo tortur.$B$BGdy byliśmy już całkiem „złamani”, zbierali tych, którzy zostali, i rzucali nas tym zbirom. Nasze ciała służyły za narzędzia w ich chorej grze: wrzucano nas do lawy albo gorzej – w otwarte, czekające ramiona krwiożerczego legionu w dole.', '', 0),
(6279, 'plPL', 'Przerażające.', 'Przerażające.', 0),
(6280, 'plPL', '$GZjawiłeś:Zjawiłaś; się akurat wtedy, gdy mieli rzucić mnie tym bestiom w dole – i za to ci dziękuję. Może ja – a raczej my, Błękitne Stado – możemy pomóc ci dalej?$B$B$GZaszedłeś:Zaszłaś; daleko, śmiertelna istoto, i wiele $gzaryzykowałeś:zaryzykowałaś;. Czy pójdziesz jeszcze dalej, by walczyć z Nefarianem i jego legionem Czarnej Skały?', '', 0),
(6281, 'plPL', 'Oczywiście.', 'Oczywiście.', 0),
(6302, 'plPL', '', 'Aaaaach!!!', 0),
(6303, 'plPL', '', 'Ty wstrętny złośliwcu! Kto cię do tego namówił?', 0),
(6304, 'plPL', '', 'To była Umi, prawda?! Ciągle robi mi psikusy, a teraz jeszcze ciebie w to wciągnęła!', 0),
(6305, 'plPL', '', '%s wzdycha.', 0),
(6381, 'plPL', 'Witaj, wędrowcze. Niewielu mnie tu odnajduje.$B$BNazywam się Rivern i szkolę mroźne szablobestie z Zimozdroju na wierzchowce.$B$BTe koty są najdziksze i najtrudniejsze do okiełznania ze wszystkich szablobestii. Tylko najbardziej zaufani i wywyższeni mogą spróbować na jednej z nich jeździć.$B$BNie sprzedam takiego wierzchowca byle komu. O nie, musisz na niego zapracować i zyskać uznanie nie tylko w moich oczach, ale i w oczach samych szablobestii.', '', 0),
(9464, 'plPL', '%s wzdycha.', '', 0),
(9575, 'plPL', 'Badam znane i nieznane żywioły naszego świata.', '', 0),
(9576, 'plPL', 'Czy jesteś tym Kształtującym Ziemię, który potrafi stworzyć elementium?', 'Czy jesteś tym Kształtującym Ziemię, który potrafi stworzyć elementium?', 0),
(9577, 'plPL', 'Elementium? Od dziesięcioleci nie słyszałem tego słowa z ust śmiertelnika.', '', 0),
(9578, 'plPL', 'Co o nim wiesz, Franzahlu?', 'Co o nim wiesz, Franzahlu?', 0),
(9579, 'plPL', 'Mój dawny uczeń, niejaki Krixix, całe życie próbował nawiązać kontakt ze spętanymi bogami podziemi. Szukał tego, co wyrasta ze zniszczonej ziemi... Tego, co powstaje tylko w wyniku zderzenia żywiołów w tytanicznym konflikcie.$B$BElementium, jak nazywają to śmiertelnicy.$B$BPewnego dnia, niemal dziesięć lat temu, poszukiwania Krixixa doprowadziły do powstania szczeliny w tym właśnie wąwozie.', '', 0),
(9580, 'plPL', 'Szczeliny?', 'Szczeliny?', 0),
(9581, 'plPL', 'Tak, dokonał czegoś, co uważano za niemożliwe. Ze szczeliny wyłonił się wysłannik Therazane!$B$BZ mojego punktu obserwacyjnego widziałem, jak goblin rozmawia z wysłannikiem Przedwiecznego Boga. To, co stało się potem, było straszne...', '', 0),
(9583, 'plPL', 'Szczelina się zamknęła, a Krixix zniknął! Pochłonięty w całości!$B$BStrzeż się, śmiertelna istoto, to, czego pragniesz, może się okazać tym, czego nie chcesz. Igrasz z istotami i tajemnymi mocami starszymi niż sam czas!$B$BJeśli Krixix żyje i ma informacje, których szukasz, możesz być $gpewien:pewna;, że ich nie odda. Stawiał czoła grozie o wiele gorszej, niż $gmógłbyś:mogłabyś; sobie wymarzyć.', '', 0),
(9664, 'plPL', 'Wszyscy drogo za to zapłacicie, gdy powrócę z głębin!', '', 0),
(9666, 'plPL', 'Ta skuta lodem kraina wystarczy na początek. Chodźcie do mnie, śmiertelnicy – a podaruję wam szybką i bolesną śmierć.', '', 0),
(9674, 'plPL', 'Jeśli wszyscy śmiertelnicy są tak tchórzliwi, pójdzie mi łatwiej, niż się zdawało!', '', 0),
(9748, 'plPL', 'Jak cudownie zobaczyć kogoś w tym odludnym zakątku świata. Chodź, przejdź się ze mną. Niech nasze ciała nawzajem się ogrzeją.', '', 0),
(9751, 'plPL', 'Znam cię jako Artoriusa Niosącego Zagładę. Pokaż się, demonie! Zmierz się ze mną!', 'Znam cię jako Artoriusa Niosącego Zagładę. Pokaż się, demonie! Zmierz się ze mną!', 0),
(9983, 'plPL', 'Jestem Kilram, mistrz topora.', '', 0),
(9986, 'plPL', '', 'Nie podchodź za blisko, $n. Jeszcze mi się ręka omsknie i rozwalę ci czaszkę obuchem młota.', 0),
(9989, 'plPL', 'Odsuń się albo przetnę cię na pół.', '', 0),
(9993, 'plPL', 'Właśnie ukończyłem nowy imploder wymiarów, dzięki któremu stanę się bogaty ponad moje najśmielsze goblińskie marzenia! Muszę tylko znaleźć zdolnego inżyniera goblińskiego, który zbuduje podłączony do niego rozdzieracz wymiarów, i go wypróbować! \n', '', 0),
(9994, 'plPL', 'Ten imploder wymiarów brzmi niebezpiecznie! Jak mogę go zrobić?', 'Ten imploder wymiarów brzmi niebezpiecznie! Jak mogę go zrobić?', 0),
(9995, 'plPL', 'Teoria jest taka, że rozwalamy cię doszczętnie potężnym wybuchem, gdziekolwiek jesteś, posyłamy cząstki przez rozdarcie wymiarów, a potem implodujemy cię z powrotem tutaj, przy maszynie. Natychmiastowy transport! Może nie działać ZA KAŻDYM razem, ale co z ciebie za $ginżynier gobliński:inżynierka goblińska;! Gdyby przeżycie było twoim priorytetem, nigdy nie $gzostałbyś prawdziwym inżynierem goblińskim:zostałabyś prawdziwą inżynierką goblińską;!\nOto przepis, którego potrzebujesz, żeby zrobić rozdzieracz wymiarów i go wypróbować!\n', '', 0),
(10000, 'plPL', 'Dobrze widzieć inżyniera, który ma dość odwagi, żeby zbudować to urządzenie. My, inżynierowie goblińscy, śmiejemy się niebezpieczeństwu w twarz!', '', 0),
(11479, 'plPL', '', 'Piękną mamy pogodę, prawda?', 0),
(11482, 'plPL', '', 'Czemu to nigdy nie ma żyrochronatomu pod ręką, kiedy jest potrzebny?', 0),
(11483, 'plPL', '', 'To ja będę się śmiać ostatnia... jeszcze zobaczą! Och, cześć, $N, nie zauważyłam cię.', 0),
(11484, 'plPL', '', 'Wynalazek, $gmój drogi:moja droga; $N, to dwa procent butelkowanej inspiracji, cztery procent ekspozycji na słońce, sześć procent szans na przejaśnienia po burzach do wczesnego popołudnia i dziewięćdziesiąt trzy procent Rumplesnicker.$B$BZaraz, czy to daje sto? Gdzieś tu miałam notatki.', 0),
(11800, 'plPL', 'Co?! Jak $gprzemknąłeś:przemknęłaś; obok mojego strażnika więz... to znaczy sługi? Cóż, chyba tak będzie najlepiej. Ostatnio sprzedaż trochę kuleje.$B$BJak mogę zaspokoić twoje piekielne potrzeby, $N?', '', 0),
(11862, 'plPL', 'Bardzo sprytnie się tu $gdostałeś:dostałaś;, $n.$B$BCo? $GZaskoczony:Zaskoczona;, że znam twoje imię? Jestem demonem, to nasza specjalność. Znam też twoje prawdziwe imię, więc lepiej kup coś drogiego.', '', 0),
(11863, 'plPL', '$GPrzyszedłeś:Przyszłaś; po różdżkę? A może po prostu robisz zapas run?$B$BChwileczkę! Czy ty po prostu próbujesz wcisnąć mi całą stertę rupieci?! Przeklęty mój nieustający przymus kupowania, kupowania, kupowania!', '', 0),
(11864, 'plPL', 'Co? Nie, nie naprawiam zbroi. Wiecznowid jest mniej więcej milę na północ, $gbracie:siostro;.$B$BA teraz kup coś albo zmykaj, zanim przywołam swojego czarnoksiężnika, żeby się tobą zajął!', '', 0),
(11913, 'plPL', 'Hej, Vi\'elu, pokaż mi swoje towary!', 'Hej, Vi\'elu, pokaż mi swoje towary!', 0),
